import{_ as t,o as s,c as i,a3 as a}from"./chunks/framework.bGC-1KKp.js";const g=JSON.parse('{"title":"Évaluation 1 — Rapport de faisabilité technique : évaluation technique","description":"","frontmatter":{"title":"Évaluation 1 — Rapport de faisabilité technique : évaluation technique","aside":false},"headers":[],"relativePath":"evaluations/evaluation-1.md","filePath":"evaluations/evaluation-1.md"}'),l={name:"evaluations/evaluation-1.md"};function r(n,e,o,u,c,d){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="evaluation-1-—-rapport-de-faisabilite-technique-evaluation-technique" tabindex="-1">Évaluation 1 — Rapport de faisabilité technique : évaluation technique <a class="header-anchor" href="#evaluation-1-—-rapport-de-faisabilite-technique-evaluation-technique" aria-label="Permalink to &quot;Évaluation 1 — Rapport de faisabilité technique : évaluation technique&quot;">​</a></h1><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>En bref</strong><br><ul class="list-disc pl-5"><li><strong>Pondération :</strong> 20 % de la note finale, dont 10 % de l&#39;évaluation pour la qualité du français.</li><li><strong>Équipe :</strong> votre équipe de la session, 2 ou 3 personnes.</li><li><strong>Remise :</strong> sur LÉA, au plus tard le <strong>mercredi 11 novembre, 18 h 30</strong> (début de la séance 7).</li><li><strong>Format :</strong> un fichier Word (<code>.docx</code>) nommé <code>eval1-equipeN-nom1-nom2-nom3.docx</code>, construit à partir du gabarit.</li><li><strong>Longueur :</strong> de 10 à 15 pages, sans compter la page de titre, la table des matières et les annexes.</li><li><strong>Retard :</strong> 10 % par jour; aucun travail accepté après 7 jours.</li></ul><a href="./../fiches/eval1-gabarit-rapport.docx" download><strong>Télécharger le gabarit du rapport (Word)</strong></a></div><hr><h2 id="la-mise-en-situation" tabindex="-1">La mise en situation <a class="header-anchor" href="#la-mise-en-situation" aria-label="Permalink to &quot;La mise en situation&quot;">​</a></h2><p>Studio Web FC, c&#39;est vous. <a href="./../mandat/">Aventure Saint-Maurice</a> vous a demandé si son projet de nouveau site est faisable. Avant de lui proposer quoi que ce soit, votre agence doit lui remettre une <strong>évaluation technique</strong> : un portrait clair et honnête de ce que son projet exige, de ce qui le limite, de ce qui pourrait mal tourner et des technologies qui existent pour le réaliser.</p><p>Ce rapport est la <strong>première moitié</strong> d&#39;un seul document. L&#39;évaluation 2 (remise le 9 décembre) le complétera avec la <strong>proposition technique</strong> : les choix recommandés, les coûts et l&#39;échéancier.</p><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><strong>Ce rapport décrit. Il ne recommande rien.</strong><br> Vous présentez les possibilités, leurs avantages, leurs limites et leurs coûts, sans trancher. Des phrases comme « nous recommandons », « le meilleur choix est » ou « il faudrait prendre » n&#39;ont pas leur place ici : elles appartiennent à l&#39;évaluation 2. Un rapport qui recommande perd des points au critère 6. </div><hr><h2 id="competence-et-elements-vises" tabindex="-1">Compétence et éléments visés <a class="header-anchor" href="#competence-et-elements-vises" aria-label="Permalink to &quot;Compétence et éléments visés&quot;">​</a></h2><p><strong>HK29 — Évaluer la faisabilité technique d&#39;un projet</strong></p><ul><li>Élément 1 : évaluer les contraintes techniques.</li><li>Élément 2 : évaluer les possibilités techniques.</li><li>Élément 5 : rédiger un rapport de faisabilité technique (première partie).</li></ul><hr><h2 id="le-lecteur" tabindex="-1">Le lecteur <a class="header-anchor" href="#le-lecteur" aria-label="Permalink to &quot;Le lecteur&quot;">​</a></h2><p>Le rapport est écrit pour <strong>Mélanie Gauthier</strong>. Elle est « correcte avec Facebook et Excel, pas plus ». Elle doit pouvoir lire le rapport sans dictionnaire.</p><ul><li>Chaque terme technique est expliqué la première fois qu&#39;il apparaît, ou évité.</li><li>Chaque affirmation importante s&#39;appuie sur le <strong>mandat</strong>, sur une <strong>source fiable</strong> ou sur <strong>vos essais</strong>.</li><li>Les tableaux résument; le texte explique ce qu&#39;ils veulent dire pour l&#39;entreprise.</li></ul><hr><h2 id="le-contenu-du-rapport" tabindex="-1">Le contenu du rapport <a class="header-anchor" href="#le-contenu-du-rapport" aria-label="Permalink to &quot;Le contenu du rapport&quot;">​</a></h2><p>Le gabarit contient déjà ces sections et des consignes dans chacune. Remplacez les consignes par votre texte.</p><h3 id="page-de-titre-et-table-des-matieres" tabindex="-1">Page de titre et table des matières <a class="header-anchor" href="#page-de-titre-et-table-des-matieres" aria-label="Permalink to &quot;Page de titre et table des matières&quot;">​</a></h3><p>Studio Web FC, le nom du client, le titre du rapport, les membres de l&#39;équipe, la date. Table des matières automatique.</p><h3 id="_1-resume" tabindex="-1">1. Résumé <a class="header-anchor" href="#_1-resume" aria-label="Permalink to &quot;1. Résumé&quot;">​</a></h3><p>Une demi-page au maximum, placée au début, pour une lectrice pressée : ce que le projet demande, les trois ou quatre constats les plus importants, et ce qui suivra dans la proposition technique. On l&#39;écrit <strong>en dernier</strong>. (Vu à la séance 5.)</p><h3 id="_2-mise-en-contexte" tabindex="-1">2. Mise en contexte <a class="header-anchor" href="#_2-mise-en-contexte" aria-label="Permalink to &quot;2. Mise en contexte&quot;">​</a></h3><ul><li>Le client, son activité et sa situation actuelle (site, outils, façon de prendre les réservations).</li><li>Ce que le client demande, et pourquoi.</li><li>La <strong>portée</strong> de ce rapport : ce qu&#39;il couvre et ce qu&#39;il ne couvre pas encore.</li></ul><h3 id="_3-les-exigences" tabindex="-1">3. Les exigences <a class="header-anchor" href="#_3-les-exigences" aria-label="Permalink to &quot;3. Les exigences&quot;">​</a></h3><ul><li><strong>3.1 Ce que le site doit faire</strong> (exigences fonctionnelles), regroupées par utilisateur : le client, le parent, le responsable de groupe, l&#39;accueil, les guides, l&#39;administratrice.</li><li><strong>3.2 Comment il doit le faire</strong> (exigences non fonctionnelles) : vitesse, sécurité, accessibilité, Loi 25 et langue, navigateurs et appareils. Chaque exigence est <strong>précise et vérifiable</strong> (« s&#39;affiche en moins de 2,5 secondes sur téléphone », pas « être rapide »).</li></ul><h3 id="_4-les-contraintes" tabindex="-1">4. Les contraintes <a class="header-anchor" href="#_4-les-contraintes" aria-label="Permalink to &quot;4. Les contraintes&quot;">​</a></h3><ul><li>Un tableau des contraintes : la contrainte, sa source dans le mandat, sa sorte (technique, organisationnelle, ressources) et son élément (budget, délai, personnel, technologie, lois).</li><li><strong>Ce qui existe déjà</strong> et que le projet doit garder, remplacer ou relier : le site Wix, le nom de domaine, les courriels, Square, Viator, l&#39;Excel.</li><li>Un court texte qui explique les <strong>trois contraintes les plus déterminantes</strong> et leur effet sur le projet.</li></ul><h3 id="_5-les-risques" tabindex="-1">5. Les risques <a class="header-anchor" href="#_5-les-risques" aria-label="Permalink to &quot;5. Les risques&quot;">​</a></h3><ul><li>Un tableau des risques (au moins 10, techniques et organisationnels), chacun évalué selon ses chances d&#39;arriver et ses conséquences.</li><li>La <strong>matrice des risques</strong>.</li><li>Une <strong>mesure</strong> pour chaque risque de la zone rouge.</li></ul><h3 id="_6-les-possibilites-techniques" tabindex="-1">6. Les possibilités techniques <a class="header-anchor" href="#_6-les-possibilites-techniques" aria-label="Permalink to &quot;6. Les possibilités techniques&quot;">​</a></h3><p>C&#39;est la partie la plus importante, et la plus nouvelle. Elle couvre les <strong>cinq questions techniques</strong>, mais pas toutes avec la même profondeur.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Q</th><th style="text-align:left;">La question</th></tr></thead><tbody><tr><td style="text-align:center;">Q1</td><td style="text-align:left;">Comment réserver et payer en ligne ?</td></tr><tr><td style="text-align:center;">Q2</td><td style="text-align:left;">Comment faire signer la décharge avant l&#39;arrivée ?</td></tr><tr><td style="text-align:center;">Q3</td><td style="text-align:left;">Sur quelle plateforme construire le site ?</td></tr><tr><td style="text-align:center;">Q4</td><td style="text-align:left;">Comment montrer les vidéos sans ralentir le site ?</td></tr><tr><td style="text-align:center;">Q5</td><td style="text-align:left;">Comment offrir le site en français et en anglais ?</td></tr></tbody></table><p><strong>Votre question</strong> (celle explorée aux séances 3 et 4), <strong>en profondeur</strong> :</p><ul><li>le <strong>besoin</strong> à combler, en rappel des sections 3 et 4;</li><li>les <strong>familles de solutions</strong> possibles (par exemple : un service spécialisé, une fonction de la plateforme du site, un développement sur mesure);</li><li><strong>deux ou trois outils</strong> existants, présentés dans un <strong>tableau de comparaison</strong> : ce qu&#39;ils font, leur modèle de prix et une <strong>estimation du coût sur trois ans</strong>, le temps pour apprendre à s&#39;en servir, la facilité d&#39;en changer plus tard, les signes qu&#39;ils existeront encore dans cinq ans;</li><li>les <strong>résultats de vos essais</strong>, résumés (le détail va en annexe A);</li><li>les <strong>avantages et les limites</strong> de chacun <strong>pour ce client-ci</strong>, et les points qui restent à vérifier.</li></ul><p><strong>Les quatre autres questions</strong>, <strong>en survol</strong>, à partir de <strong>votre propre recherche documentaire</strong> (sans essais) :</p><ul><li>le <strong>besoin</strong> à combler, en quelques lignes;</li><li><strong>deux outils</strong> existants, dans un <strong>tableau court</strong> : ce qu&#39;ils font, leur modèle de prix, une <strong>estimation du coût sur trois ans</strong> et la principale limite pour ce client;</li><li>les <strong>points qu&#39;un essai devrait vérifier</strong> avant de pouvoir choisir.</li></ul><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Votre question, et les quatre autres</strong><br> Pour les quatre autres questions, appliquez la méthode du Lab 03 : pages de prix officielles, documentation de l&#39;outil, témoignages d&#39;utilisateurs, sources classées selon leur fiabilité. Sans essai, vous ne pouvez pas affirmer qu&#39;un outil « fonctionne bien » : écrivez ce que la source annonce, citez-la, et dites ce qui resterait à vérifier. À titre indicatif : de 3 à 4 pages pour votre question, environ une page pour chacune des autres. </div><h3 id="_7-les-problemes-techniques-a-prevoir-et-les-questions-au-client" tabindex="-1">7. Les problèmes techniques à prévoir et les questions au client <a class="header-anchor" href="#_7-les-problemes-techniques-a-prevoir-et-les-questions-au-client" aria-label="Permalink to &quot;7. Les problèmes techniques à prévoir et les questions au client&quot;">​</a></h3><ul><li>Les problèmes techniques qui pourraient bloquer ou retarder le projet, et ce qu&#39;il faut vérifier pour chacun.</li><li>Au moins <strong>huit questions à poser au client</strong> avant de pouvoir faire une proposition, formulées sans jargon. Elles serviront à la rencontre de la séance 9.</li></ul><h3 id="_8-references" tabindex="-1">8. Références <a class="header-anchor" href="#_8-references" aria-label="Permalink to &quot;8. Références&quot;">​</a></h3><p>Toutes les sources citées, en style <a href="https://boite-outils.bib.umontreal.ca/citer/apa?p=5248896">APA 7</a>. Une source publicitaire peut être citée pour un prix ou une fonction annoncée, jamais comme preuve qu&#39;un outil est bon.</p><h3 id="annexes" tabindex="-1">Annexes <a class="header-anchor" href="#annexes" aria-label="Permalink to &quot;Annexes&quot;">​</a></h3><ul><li><strong>A. Résultats des essais</strong> de votre équipe : le plan, les mesures, les captures d&#39;écran.</li><li><strong>B. Déclaration d&#39;utilisation de l&#39;IA générative</strong> (voir plus bas).</li><li><strong>C. Contribution des membres</strong> : qui a fait quoi, signé par tous.</li></ul><hr><h2 id="l-intelligence-artificielle-generative" tabindex="-1">L&#39;intelligence artificielle générative <a class="header-anchor" href="#l-intelligence-artificielle-generative" aria-label="Permalink to &quot;L&#39;intelligence artificielle générative&quot;">​</a></h2><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Ce qui est permis</strong> (et doit être déclaré) <ul class="list-disc pl-5"><li>Se faire expliquer une notion ou un terme technique.</li><li>Trouver des <strong>noms d&#39;outils</strong> à explorer, à condition de tout vérifier dans des sources fiables ou par un essai.</li><li>Générer des <strong>données fictives</strong> pour vos essais (noms de clients, horaires).</li><li>Corriger le français avec un outil d&#39;IA générative. Les correcteurs comme Antidote ou celui de Word sont permis.</li></ul><strong>Ce qui n&#39;est pas permis</strong><ul class="list-disc pl-5"><li>Rédiger, reformuler ou résumer des parties du rapport.</li><li>Produire les analyses : les contraintes, les exigences, les risques, les comparaisons.</li></ul> Dans l&#39;annexe B, indiquez pour chaque usage : l&#39;outil, ce que vous lui avez demandé, et ce que vous avez fait de sa réponse. Si vous n&#39;avez utilisé aucun outil d&#39;IA, écrivez-le. Tout usage non déclaré sera traité selon la procédure PR-211. </div><hr><h2 id="la-grille-d-evaluation" tabindex="-1">La grille d&#39;évaluation <a class="header-anchor" href="#la-grille-d-evaluation" aria-label="Permalink to &quot;La grille d&#39;évaluation&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Critère</th><th style="text-align:left;">Ce qui est évalué</th><th style="text-align:right;">Points</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Organisation et clarté</strong></td><td style="text-align:left;">Structure du gabarit respectée, résumé utile, tableaux lisibles, texte compréhensible pour une non-spécialiste, termes techniques expliqués</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Mise en contexte</strong></td><td style="text-align:left;">Situation actuelle juste, demande du client bien comprise, portée du rapport claire</td><td style="text-align:right;">5</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>Exigences</strong></td><td style="text-align:left;">Exigences fonctionnelles complètes pour tous les utilisateurs; exigences non fonctionnelles précises et vérifiables dans les cinq catégories</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>Contraintes</strong></td><td style="text-align:left;">Contraintes nombreuses, justes, sourcées et bien classées; l&#39;existant est inventorié; les contraintes déterminantes sont expliquées</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>Risques</strong></td><td style="text-align:left;">Risques variés et réalistes, évaluation cohérente, mesures concrètes pour la zone rouge</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Possibilités techniques</strong></td><td style="text-align:left;">La question de l&#39;équipe traitée en profondeur, avec des essais rigoureux; les quatre autres couvertes par la recherche de l&#39;équipe; outils pertinents comparés sur les mêmes critères; coûts estimés sur trois ans; avantages et limites pour ce client; sources fiables; <strong>aucune recommandation</strong></td><td style="text-align:right;">25</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Problèmes à prévoir et questions au client</strong></td><td style="text-align:left;">Problèmes réels et précis; questions utiles et formulées pour le client</td><td style="text-align:right;">5</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Qualité du français</strong></td><td style="text-align:left;">Évaluée sur un extrait d&#39;environ 150 mots choisi par l&#39;enseignant, selon la Politique du français de la DFCSE</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;"></td><td style="text-align:left;"></td><td style="text-align:left;"><strong>Total</strong></td><td style="text-align:right;"><strong>100</strong></td></tr></tbody></table><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Ce qui fait perdre des points rapidement</strong><ul class="list-disc pl-5"><li>Une recommandation, même glissée dans une phrase.</li><li>Une affirmation sur un outil sans source, ou appuyée seulement sur une source publicitaire.</li><li>Un prix en dollars américains présenté comme s&#39;il était en dollars canadiens, ou un coût sans les frais annuels.</li><li>Une contrainte ou un risque générique qu&#39;on pourrait copier dans n&#39;importe quel rapport (« le budget est limité »).</li><li>Du jargon non expliqué.</li><li>Les annexes B ou C manquantes.</li></ul></div><hr><h2 id="le-calendrier-conseille" tabindex="-1">Le calendrier conseillé <a class="header-anchor" href="#le-calendrier-conseille" aria-label="Permalink to &quot;Le calendrier conseillé&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Séance</th><th style="text-align:left;">Date</th><th style="text-align:left;">Ce que vous y faites pour le rapport</th></tr></thead><tbody><tr><td style="text-align:center;">2</td><td style="text-align:left;">30 sept.</td><td style="text-align:left;">Lab 02 : sections 3, 4, 5 et 7 en version brute</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;">7 oct.</td><td style="text-align:left;">Lab 03 : plan d&#39;essai pour votre question</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;">21 oct.</td><td style="text-align:left;">Essais des outils pour votre question; retour en grand groupe sur les cinq questions → section 6</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;">28 oct.</td><td style="text-align:left;">Organisation d&#39;un rapport, écrire pour un client → résumé et réécriture</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;">4 nov.</td><td style="text-align:left;">Atelier de révision et de français; période de questions</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;">11 nov.</td><td style="text-align:left;"><strong>Remise</strong> avant 18 h 30</td></tr></tbody></table><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Un conseil</strong><br> N&#39;attendez pas la séance 6 pour écrire. Les sections 3, 4 et 5 peuvent être mises au propre <strong>dès cette semaine</strong> à partir de votre fiche du Lab 02, avec les ajouts notés pendant la correction commentée en classe. </div><hr><h2 id="la-liste-de-verification-avant-la-remise" tabindex="-1">La liste de vérification avant la remise <a class="header-anchor" href="#la-liste-de-verification-avant-la-remise" aria-label="Permalink to &quot;La liste de vérification avant la remise&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Le rapport suit le gabarit, avec une table des matières à jour</span></label></li><li><label><input type="checkbox"><span class="check-text">Le résumé tient en une demi-page et a été écrit en dernier</span></label></li><li><label><input type="checkbox"><span class="check-text">Les exigences non fonctionnelles sont mesurables</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque contrainte a sa source dans le mandat</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque risque de la zone rouge a sa mesure</span></label></li><li><label><input type="checkbox"><span class="check-text">Votre question est traitée en profondeur, avec un tableau complet et les résultats de vos essais; les quatre autres ont chacune un tableau court</span></label></li><li><label><input type="checkbox"><span class="check-text">Les coûts sont en dollars canadiens, sur trois ans, avec les hypothèses indiquées</span></label></li><li><label><input type="checkbox"><span class="check-text">Une recherche du mot « recommand » dans le document ne trouve aucune recommandation</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque affirmation sur un outil est appuyée par une source citée; les références sont en <a href="https://boite-outils.bib.umontreal.ca/citer/apa?p=5248896">APA 7</a></span></label></li><li><label><input type="checkbox"><span class="check-text">Le texte a été relu par une autre personne de l&#39;équipe que celle qui l&#39;a écrit, et passé dans un correcteur</span></label></li><li><label><input type="checkbox"><span class="check-text">Les annexes A, B et C sont présentes</span></label></li><li><label><input type="checkbox"><span class="check-text">Le fichier est nommé correctement et déposé sur LÉA avant 18 h 30 le 11 novembre</span></label></li></ul>',58)])])}const h=t(l,[["render",r]]);export{g as __pageData,h as default};
